// src/usecases/init/initProject.ts
import fs from "fs";
import path from "path";
var BOOKIPI_DIR = ".bookipi";
var CREDENTIALS_FILE = "credentials.json";
var PROJECT_ROOT_MARKERS = [".git", "package.json", "README.md", BOOKIPI_DIR];
var COWORK_MD_CONTENT = `# Bookipi workspace \u2014 Cowork conventions

This folder is a self-contained Bookipi workspace. Credentials, handles, and
config live in \`.bookipi/\`. The folder can be mounted into a Cowork project
for an isolated, portable workspace.

## Multi-agent flow

For new CLI features:
- pm \u2192 spec at \`/tmp/spec-*.md\`, gate for human review
- backend-engineer \u2192 src/usecases/, verify file lands in main via \`git status\`
- frontend-engineer \u2192 src/commands/ + tests/smoke/ + skill docs
- qa \u2192 run \`pnpm run test:smoke\` and \`pnpm run lint:skill-docs\`

## Hard rules

- Validate flag inputs BEFORE resolving handles (cheap local checks first).
- Work in the main working tree, never in \`.claude/worktrees/\`.
- Verify file existence in main between agent dispatches.
- After every shipped command, add a smoke test in \`tests/smoke/\`.

## Release flow

- One command: \`pnpm run release:patch\` (or \`:minor\` / \`:major\`).
- Includes bump + build + commit + tag + push.
- GitHub Actions creates the \`.skill\` release on tag push.
- npm publish is deferred until credentials are wired up.
`;
function checkCoworkPersistence(targetPath) {
  const inSandbox = fs.existsSync("/sessions") || fs.existsSync("/mnt/user-data");
  if (!inSandbox) {
    return { ephemeral: false, mountedFolders: [] };
  }
  const resolved = path.resolve(targetPath);
  const mountDirs = coworkMountDirs();
  const underMount = mountDirs.some((d) => resolved.startsWith(`${d}${path.sep}`)) || /^\/sessions\/[^/]+\/mnt\/[^/]/.test(resolved) || resolved.startsWith("/mnt/");
  if (underMount) {
    return { ephemeral: false, mountedFolders: [] };
  }
  const mountedFolders = [];
  for (const mntDir of mountDirs) {
    try {
      for (const folder of fs.readdirSync(mntDir)) {
        if (folder.startsWith(".")) continue;
        mountedFolders.push(path.join(mntDir, folder));
      }
    } catch {
    }
  }
  return { ephemeral: true, mountedFolders };
}
async function initProject(opts) {
  const { targetPath, force, withCoworkInstructions } = opts;
  const configDir = path.join(targetPath, BOOKIPI_DIR);
  const credentialsPath = path.join(configDir, CREDENTIALS_FILE);
  if (!force) {
    const persistence = checkCoworkPersistence(targetPath);
    if (persistence.ephemeral) {
      const suggestion = persistence.mountedFolders.length > 0 ? ` Run it against the mounted project folder instead, e.g.: bookipi init ${persistence.mountedFolders[0]}` : ` Add a local folder to this Cowork project first, then run init against its /sessions/<id>/mnt/<folder> path.`;
      throw new Error(
        `${targetPath} is inside the Cowork sandbox and is wiped when this session ends \u2014 credentials saved here would NOT persist (you'd be asked to log in again every session).${suggestion} (Pass --force only for a deliberately throwaway login.)`
      );
    }
  }
  if (!force && fs.existsSync(credentialsPath)) {
    throw new Error(
      `Credentials already exist at ${credentialsPath}. Re-run with --force to overwrite.`
    );
  }
  if (!force && fs.existsSync(targetPath)) {
    const entries = fs.readdirSync(targetPath);
    if (entries.length > 0) {
      const hasMarker = PROJECT_ROOT_MARKERS.some(
        (marker) => fs.existsSync(path.join(targetPath, marker))
      );
      if (!hasMarker) {
        throw new Error(
          `Target folder doesn't look like a project root. Re-run with --force to proceed anyway.`
        );
      }
    }
  }
  try {
    fs.mkdirSync(configDir, { recursive: true });
  } catch (err2) {
    const e = err2;
    if (e.code === "EACCES" || e.code === "EPERM") {
      throw new Error(`Cannot write to ${targetPath}: permission denied.`);
    }
    throw err2;
  }
  const gitignorePath = path.join(targetPath, ".gitignore");
  const gitignoreUpdated = updateGitignore(gitignorePath);
  let coworkInstructionsWritten = false;
  if (withCoworkInstructions) {
    const coworkPath = path.join(targetPath, "COWORK.md");
    fs.writeFileSync(coworkPath, COWORK_MD_CONTENT, "utf-8");
    coworkInstructionsWritten = true;
  }
  return { configDir, gitignoreUpdated, coworkInstructionsWritten };
}
function updateGitignore(gitignorePath) {
  const entry = ".bookipi/";
  if (!fs.existsSync(gitignorePath)) {
    fs.writeFileSync(gitignorePath, `${entry}
`, "utf-8");
    return true;
  }
  const existing = fs.readFileSync(gitignorePath, "utf-8");
  const lines = existing.split("\n");
  const alreadyPresent = lines.some((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith("#")) return false;
    return trimmed === ".bookipi/" || trimmed === ".bookipi";
  });
  if (alreadyPresent) return false;
  const trailingNewline = existing.endsWith("\n") ? "" : "\n";
  fs.writeFileSync(gitignorePath, `${existing}${trailingNewline}${entry}
`, "utf-8");
  return true;
}

