var SEARCH_INVOICES_QUERY = `
  query SearchInvoices($docType: Int, $filter: SearchFilterInput!, $paginate: SearchPaginateInput, $sort: String) {
    searchInvoices(
      docType: $docType
      filter: $filter
      paginate: $paginate
      sort: $sort
    ) {
      items {
        ${INVOICE_CORE_FIELDS}
        quickbooksId
      }
      pageInfo {${PAGE_INFO_FIELDS}      }
    }
  }
`;
async function listInvoices(options = {}) {
  const {
    status = [...VALID_STATUSES],
    docType = 1,
    customerId,
    start,
    end,
    search,
    page = 1,
    perPage = 15,
    sort = "createdAt_desc",
    companyId
  } = options;
  const variables = {
    docType,
    filter: {
      search: search ?? null,
      status,
      ...customerId ? { customerId } : {},
      ...start ? { start } : {},
      ...end ? { end } : {}
    },
    paginate: {
      fetchAll: false,
      page,
      perPage
    },
    sort
  };
  return bookipiGraphql({
    query: SEARCH_INVOICES_QUERY,
    variables,
    ...companyId ? { companyId } : {}
  });
}

// src/usecases/invoice/documentTypes.ts
var DOCUMENT_TYPES = [
  { code: 0, name: "estimate", label: "Estimate", prefix: "EST" },
  { code: 1, name: "invoice", label: "Invoice", prefix: "INV" },
  { code: 2, name: "credit-note", label: "Credit Note", prefix: "CN" },
  { code: 3, name: "delivery-note", label: "Delivery Note", prefix: "DN" },
  { code: 4, name: "purchase-order", label: "Purchase Order", prefix: "PO" }
];
var DOCUMENT_TYPE_NAMES = DOCUMENT_TYPES.map((d) => d.name);
var ALIASES = {
  quote: "estimate",
  quotation: "estimate",
  creditnote: "credit-note",
  credit_note: "credit-note",
  deliverynote: "delivery-note",
  delivery_note: "delivery-note",
  purchaseorder: "purchase-order",
  purchase_order: "purchase-order",
  po: "purchase-order"
};
function resolveDocumentType(input) {
  if (typeof input === "number" || /^\d+$/.test(String(input).trim())) {
    const code = Number(input);
    const byCode = DOCUMENT_TYPES.find((d) => d.code === code);
    if (!byCode) {
      throw new Error(
        `Invalid document type code ${code}. Valid: ${DOCUMENT_TYPES.map((d) => `${d.code}=${d.name}`).join(", ")}`
      );
    }
    return byCode;
  }
  const key2 = String(input).trim().toLowerCase().replace(/\s+/g, "-");
  const canonical = ALIASES[key2] ?? ALIASES[key2.replace(/-/g, "")] ?? key2;
  const byName = DOCUMENT_TYPES.find((d) => d.name === canonical);
  if (!byName) {
    throw new Error(
      `Unknown document type '${input}'. Valid types: ${DOCUMENT_TYPE_NAMES.join(", ")}.`
    );
  }
  return byName;
}
function documentTypeByCode(code) {
  return DOCUMENT_TYPES.find((d) => d.code === code) ?? DOCUMENT_TYPES.find((d) => d.code === 1);
}

