// src/core/format/liveReload.ts
var LIVE_REFRESH_SECONDS = 2;
function injectLiveReload(html, seconds = LIVE_REFRESH_SECONDS) {
  const tag = `<meta http-equiv="refresh" content="${seconds}">`;
  const head = html.match(/<head[^>]*>/i);
  if (head) {
    const at = head.index + head[0].length;
    return html.slice(0, at) + tag + html.slice(at);
  }
  const htmlTag = html.match(/<html[^>]*>/i);
  if (htmlTag) {
    const at = htmlTag.index + htmlTag[0].length;
    return html.slice(0, at) + tag + html.slice(at);
  }
  return tag + html;
}

// src/commands/invoice/preview.ts
var previewCommand = new Command("preview").description(
  "Render a printable preview of an invoice (the same layout the web app uses). Writes an HTML file by default; --pdf converts it to a PDF."
).argument("<id>", "Invoice ID or handle (@i1)").option(
  "-o, --output <path>",
  "Write the preview to this path (default: a temp file)"
).option(
  "--pdf",
  "Convert the preview to a PDF via the Bookipi PDF service (requires network)"
).option("--stdout", "Print the preview to stdout instead of writing a file").option(
  "--live",
  "Inject an auto-refresh so an open browser tab updates itself after each re-render (HTML only \u2014 ideal for live editing)"
).option(
  "--embed",
  "Write an embeddable, self-contained fragment (head <style> + body only, remote <img> inlined as data URIs) ready to render as an Artifact without further editing. Keeps the full HTML out of an agent's context (HTML only; ignored with --pdf)."
).option("--json", "Output JSON metadata { file, no, _id }").action(
  withErrors(async (id, opts) => {
    const registry3 = HandleRegistry.getInstance();
    const resolvedId = registry3.resolve(id);
    const invoice = await getInvoice(resolvedId);
    const companyId = invoice?.company || getDefaultCompany() || "";
    const company = await resolveRenderCompany(companyId);
    let html = await renderInvoiceHtml(invoice, company);
    if (opts.embed && !opts.pdf) {
      const r = await inlineRemoteImages(html);
      html = toEmbeddableFragment(r.html);
      if (r.failed > 0) {
        process.stderr.write(
          `  \u2022 Inlined ${r.inlined} image(s); ${r.failed} could not be fetched (they may show broken in a sandboxed viewer \u2014 check the image host is allowed).
`
        );
      }
    }
    const rawNo = invoice?.no ? String(invoice.no).trim() : "";
    const no = rawNo || resolvedId;
    if (opts.pdf) {
      if (opts.live) {
        console.error(
          "(--live has no effect with --pdf \u2014 a PDF can't auto-refresh.)"
        );
      }
      const pdf = await htmlToPdf(html);
      if (opts.stdout) {
        process.stdout.write(pdf);
        return;
      }
      const outPath2 = resolve(
        opts.output || join2(tmpdir2(), `bookipi-${no}-${resolvedId}.pdf`)
      );
      writeFileSync(outPath2, pdf);
      sweepTempRenders({ keep: outPath2 });
      if (opts.json) {
        console.log(
          JSON.stringify(
            { file: outPath2, no, _id: resolvedId, format: "pdf" },
            null,
            2
          )
        );
        return;
      }
      console.log(`\u2705 Invoice PDF rendered for **${no}**
`);
      console.log(`   \u{1F4C4} file://${outPath2}`);
      console.log(`
\u{1F4A1} Open that file to view or print the invoice.`);
      return;
    }
    const htmlOut = opts.live ? injectLiveReload(html, LIVE_REFRESH_SECONDS) : html;
    if (opts.stdout) {
      process.stdout.write(htmlOut);
      return;
    }
    const outPath = resolve(
      opts.output || join2(tmpdir2(), `bookipi-${no}-${resolvedId}.html`)
    );
    writeFileSync(outPath, htmlOut, "utf8");
    sweepTempRenders({ keep: outPath });
    if (opts.json) {
      console.log(
        JSON.stringify(
          { file: outPath, no, _id: resolvedId, live: !!opts.live },
          null,
          2
        )
      );
      return;
    }
    console.log(`\u2705 Invoice preview rendered for **${no}**
`);
    console.log(`   \u{1F4C4} file://${outPath}`);
    if (opts.live) {
      console.log(
        `
\u21BB Live \u2014 the page reloads itself every ${LIVE_REFRESH_SECONDS}s. Keep the tab open and it updates as you edit.`
      );
    } else {
      console.log(
        `
\u{1F4A1} Open that file in a browser to view or print the invoice.`
      );
    }
  })
);

