// src/usecases/invoice/invoicePayment.ts
function buildMarkPaidPayments(inv, opts) {
  const total = typeof inv?.total === "number" ? inv.total : 0;
  const amountDue = typeof inv?.amountDue === "number" ? inv.amountDue : total;
  const existing = Array.isArray(inv?.payments) ? inv.payments : [];
  const amount = typeof opts.amount === "number" ? opts.amount : amountDue;
  if (!(amount > 0)) {
    throw new Error("Nothing to record \u2014 this invoice has no outstanding balance.");
  }
  const payment = {
    amount,
    channel: "manual",
    date: opts.date || opts.nowIso,
    method: opts.method || "cash",
    note: opts.note || ""
  };
  return { payments: [...existing, payment], recordedAmount: amount };
}
async function markInvoicePaid(invoiceId, opts = {}, now2 = () => /* @__PURE__ */ new Date()) {
  const inv = await getInvoice(invoiceId);
  const { payments, recordedAmount } = buildMarkPaidPayments(inv, {
    ...opts,
    nowIso: now2().toISOString()
  });
  const data = await updateInvoice(invoiceId, { payments });
  const rec = data?.invoicesUpdateOne?.record;
  return {
    invoiceNo: rec?.no ?? inv?.no ?? invoiceId,
    paymentStatus: rec?.paymentStatus ?? null,
    amountDue: rec?.amountDue ?? null,
    total: rec?.total ?? null,
    recordedAmount
  };
}
async function voidInvoicePayments(invoiceId) {
  const data = await updateInvoice(invoiceId, { payments: [] });
  const rec = data?.invoicesUpdateOne?.record;
  return {
    invoiceNo: rec?.no ?? invoiceId,
    paymentStatus: rec?.paymentStatus ?? null,
    amountDue: rec?.amountDue ?? null,
    total: rec?.total ?? null
  };
}

