// src/core/formatters/CustomerFormatter.ts
var CustomerFormatter = class extends BaseFormatter {
  registry;
  constructor() {
    super();
    this.registry = HandleRegistry.getInstance();
  }
  format(data, options) {
    const jsonMode = options?.json === true;
    if (jsonMode) {
      return JSON.stringify(data, null, 2);
    }
    if (Array.isArray(data)) {
      return this.formatList(data);
    } else if (data.searchCustomers?.items && Array.isArray(data.searchCustomers.items)) {
      return this.formatList(
        data.searchCustomers.items,
        data.searchCustomers.pageInfo
      );
    } else {
      return this.formatSingle(data);
    }
  }
  formatSingle(customer) {
    const customerId = customer._id || "unknown";
    const handle = this.registry.register("c", customerId);
    const name = this.getCustomerName(customer);
    let output = `# Customer: ${name} [${handle}]
`;
    output += this.section("Details");
    output += this.listItem("Name", name);
    if (customer.companyName) {
      output += this.listItem("Company", customer.companyName);
    }
    if (customer.individualCompanyName) {
      output += this.listItem(
        "Individual Company",
        customer.individualCompanyName
      );
    }
    if (customer.jobTitle) {
      output += this.listItem("Job Title", customer.jobTitle);
    }
    if (customer.email) output += this.listItem("Email", customer.email);
    if (customer.mobile) output += this.listItem("Mobile", customer.mobile);
    if (customer.phone) output += this.listItem("Phone", customer.phone);
    if (customer.fax) output += this.listItem("Fax", customer.fax);
    if (customer.businessNumber) {
      output += this.listItem("Business No", customer.businessNumber);
    }
    if (customer.total !== void 0) {
      output += this.listItem("Total Billed", this.formatCurrency(customer.total));
    }
    if (customer.amountDue !== void 0) {
      output += this.listItem("Amount Due", this.formatCurrency(customer.amountDue));
    }
    if (customer.documentCount != null && customer.documentCount > 0) {
      output += this.listItem("Invoices", customer.documentCount);
    }
    if (customer.address) {
      const addr = this.formatAddress(customer.address);
      if (addr) output += this.listItem("Address", addr);
    }
    if (customer.tags && customer.tags.length > 0) {
      const tagNames = customer.tags.map((t) => t.name).join(", ");
      output += this.listItem("Tags", tagNames);
    }
    if (customer.notes) output += this.listItem("Notes", customer.notes);
    output += this.separator();
    output += this.nextActions("Next actions", [
      `Create invoice: \`bookipi invoice create --company <company_id> --customer ${handle} --number INV-XXX --date YYYY-MM-DD --item '{"name":"...","price":0,"quantity":1}'\``,
      `List all customers: \`bookipi customer list\``
    ]);
    return output;
  }
  formatList(customers, meta3) {
    let output = `# Customers (${customers.length} found)
`;
    if (customers.length === 0) {
      output += "\nNo customers found.\n";
      return output;
    }
    const headers = ["Handle", "Name", "Email", "Total", "Due"];
    const rows = customers.map((customer) => {
      const customerId = customer._id || "unknown";
      const handle = this.registry.register("c", customerId);
      const name = this.getCustomerName(customer);
      const email3 = customer.email || "N/A";
      const total = this.formatCurrency(customer.total);
      const due = this.formatCurrency(customer.amountDue);
      return [handle, name, email3, total, due];
    });
    output += "\n";
    output += this.createTable(headers, rows, [3, 4]);
    if (meta3) {
      output += `
Page ${meta3.currentPage} of ${meta3.pageCount} (${meta3.itemCount} total)
`;
    }
    output += this.separator();
    output += this.nextActions("Actions", [
      "View customer: `bookipi customer list` then use handle",
      'Search: `bookipi customer list --search "name"`',
      "Next page: `bookipi customer list --page 2`"
    ]);
    return output;
  }
  getCustomerName(customer) {
    return customerName(customer);
  }
  formatAddress(addr) {
    const parts2 = [
      addr.address1,
      addr.address2,
      addr.address3,
      [addr.city, addr.state, addr.zip].filter(Boolean).join(" "),
      addr.country
    ].filter(Boolean);
    return parts2.join(", ");
  }
};

