// src/core/api/unwrapRemoveMany.ts
function unwrapRemoveMany(value) {
  const removed = Array.isArray(value) ? value[0] : value;
  if (!removed || !removed.recordId && !removed.record) return null;
  return removed;
}

// src/usecases/customer/deleteCustomer.ts
var CUSTOMERS_REMOVE_MANY_MUTATION = `
  mutation CustomersRemoveMany($filter: CompatRemoveOnecustomersInput!) {
    customersRemoveMany(filter: $filter) {
      records {
        recordId
        record {
          _id
          companyName
          firstName
          lastName
          individualCompanyName
          createdAt
          updatedAt
        }
      }
    }
  }
`;
async function deleteCustomer(id) {
  const data = await bookipiGraphql({
    query: CUSTOMERS_REMOVE_MANY_MUTATION,
    variables: { filter: { _id: id } }
  });
  const removed = unwrapRemoveMany(
    data.customersRemoveMany?.records
  );
  if (!removed) throw new Error(`Customer not found: ${id}`);
  return removed.record ?? { _id: removed.recordId };
}

