// src/commands/customer/send-email.ts
function looksLikeHtml(s) {
  return /<[a-z][\s\S]*?>/i.test(s.trim());
}
function deriveHtmlAndText(body) {
  if (looksLikeHtml(body)) {
    const text = body.replace(/<br\s*\/?>(?=)/gi, "\n").replace(/<\/p>/gi, "\n\n").replace(/<[^>]+>/g, "").replace(/\n{3,}/g, "\n\n").trim();
    return { html: body, text };
  }
  const escaped = body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const html = `<p>${escaped.replace(/\n/g, "<br>")}</p>`;
  return { html, text: body };
}
var sendEmailCommand = new Command("send-email").description(
  "Send a standalone email to a customer. Returns server-side delivery status. NOTE: depends on a backend recaptcha-bypass for authenticated CLI requests; until that ships you will see a recaptcha error from the server."
).argument("<customer>", "Customer ID, handle (@c1), or name").requiredOption(
  "--to <email>",
  "Recipient email (repeatable, or comma-separated)",
  collectList,
  []
).option(
  "--cc <email>",
  "CC email (repeatable, or comma-separated)",
  collectList,
  []
).option(
  "--bcc <email>",
  "BCC email (repeatable, or comma-separated)",
  collectList,
  []
).requiredOption("--subject <text>", "Email subject").requiredOption(
  "--body <text>",
  "Email body. HTML is auto-detected; otherwise wrapped in <p> with newlines as <br>."
).option(
  "--reply-to <id>",
  "MongoID of the user/team-member whose address replies should go to"
).option(
  "--project-pipeline <id>",
  "MongoID of the project pipeline this email belongs to (optional)"
).option("--json", "Output raw JSON instead of formatted").action(
  withErrors(async (customer, opts) => {
    if (!Array.isArray(opts.to) || opts.to.length === 0) {
      failWith("--to is required (at least one recipient)", { json: opts.json });
    }
    const customerId = await resolveCustomerId(customer);
    const { html, text } = deriveHtmlAndText(opts.body);
    const result = await sendCustomerEmail({
      customerId,
      to: opts.to,
      cc: opts.cc,
      bcc: opts.bcc,
      subject: opts.subject,
      html,
      text,
      replyTo: opts.replyTo ?? null,
      projectPipelineId: opts.projectPipeline ?? null
    });
    const payload = result?.customersSendEmail ?? {};
    const statusCode = payload.statusCode;
    const message = payload.message ?? "Email sent.";
    if (opts.json) {
      console.log(
        JSON.stringify(
          {
            customerId,
            to: opts.to,
            subject: opts.subject,
            statusCode,
            message
          },
          null,
          2
        )
      );
      return;
    }
    const ok2 = !statusCode || statusCode >= 200 && statusCode < 300;
    console.log(`${ok2 ? "\u2705" : "\u26A0"} ${message}`);
    console.log(`   To: ${opts.to.join(", ")}`);
    if (opts.cc && opts.cc.length > 0) console.log(`   Cc: ${opts.cc.join(", ")}`);
    if (opts.bcc && opts.bcc.length > 0) console.log(`   Bcc: ${opts.bcc.join(", ")}`);
    console.log(`   Subject: ${opts.subject}`);
    if (statusCode != null) console.log(`   Status: ${statusCode}`);
  })
);

