// src/usecases/customer/getCustomerPayments.ts
function paymentsFromInvoices(invoices, truncated = false) {
  const rows = [];
  const invoicesWithPayments = /* @__PURE__ */ new Set();
  for (const inv of invoices || []) {
    const payments = Array.isArray(inv?.payments) ? inv.payments : [];
    for (const p of payments) {
      if (typeof p?.amount !== "number") continue;
      rows.push({
        date: p.date || null,
        invoiceNo: inv.no || "N/A",
        invoiceId: inv._id,
        amount: p.amount,
        method: p.method ?? null,
        brand: p.brand ?? null,
        last4: p.last4 ?? null,
        channel: p.channel ?? null,
        note: p.note ?? null
      });
      if (inv._id) invoicesWithPayments.add(inv._id);
    }
  }
  rows.sort((a, b) => {
    const ta = a.date ? new Date(a.date).getTime() : -Infinity;
    const tb = b.date ? new Date(b.date).getTime() : -Infinity;
    return tb - ta;
  });
  return {
    rows,
    totalCollected: rows.reduce((s, r) => s + r.amount, 0),
    paymentCount: rows.length,
    invoicesWithPayments: invoicesWithPayments.size,
    truncated
  };
}
async function getCustomerPayments(customerId, maxPages = 20, companyId) {
  const perPage = 200;
  const invoices = [];
  let page = 1;
  let truncated = false;
  for (; page <= maxPages; page++) {
    const data = await listInvoices({
      customerId,
      page,
      perPage,
      sort: "createdAt_desc",
      // Scope every page of the scan, not just the first.
      ...companyId ? { companyId } : {}
    });
    const items = data?.searchInvoices?.items || [];
    invoices.push(...items);
    if (!data?.searchInvoices?.pageInfo?.hasNextPage) break;
    if (page === maxPages) truncated = true;
  }
  return paymentsFromInvoices(invoices, truncated);
}

