// src/core/formatters/ItemFormatter.ts
var ItemFormatter = class extends BaseFormatter {
  registry;
  constructor() {
    super();
    this.registry = HandleRegistry.getInstance();
  }
  format(data, options) {
    const jsonMode = options?.json === true;
    if (jsonMode) {
      return JSON.stringify(data, null, 2);
    }
    if (Array.isArray(data)) {
      return this.formatList(data);
    } else if (data.searchItems?.items && Array.isArray(data.searchItems.items)) {
      return this.formatList(
        data.searchItems.items,
        data.searchItems.pageInfo
      );
    } else {
      return this.formatSingle(data);
    }
  }
  formatSingle(item) {
    const itemId = item._id || "unknown";
    const handle = this.registry.register("t", itemId);
    let output = `# Item: ${item.name || "N/A"} [${handle}]
`;
    output += this.section("Details");
    output += this.listItem("Name", item.name || "N/A");
    if (item.productCode) output += this.listItem("Code", item.productCode);
    if (item.description) output += this.listItem("Description", item.description);
    output += this.listItem("Price", this.formatCurrency(item.price));
    if (item.unitType) output += this.listItem("Unit", item.unitType);
    if (item.taxCode) output += this.listItem("Tax Code", item.taxCode);
    if (item.taxRate != null) output += this.listItem("Tax Rate", `${item.taxRate}%`);
    output += this.separator();
    output += this.nextActions("Next actions", [
      `Use in invoice: \`bookipi invoice create ... --item '{"name":"${item.name}","price":${item.price ?? 0},"quantity":1}'\``,
      `List all items: \`bookipi item list\``
    ]);
    return output;
  }
  formatList(items, meta3) {
    let output = `# Items (${items.length} found)
`;
    if (items.length === 0) {
      output += "\nNo items found.\n";
      return output;
    }
    const headers = ["Handle", "Name", "Code", "Price", "Unit"];
    const rows = items.map((item) => {
      const itemId = item._id || "unknown";
      const handle = this.registry.register("t", itemId);
      return [
        handle,
        item.name || "N/A",
        item.productCode || "\u2014",
        this.formatCurrency(item.price),
        item.unitType || "\u2014"
      ];
    });
    output += "\n";
    output += this.createTable(headers, rows, [3]);
    if (meta3) {
      output += `
Page ${meta3.currentPage} of ${meta3.pageCount} (${meta3.itemCount} total)
`;
    }
    output += this.separator();
    output += this.nextActions("Actions", [
      'Search: `bookipi item list --search "name"`',
      "Next page: `bookipi item list --page 2`"
    ]);
    return output;
  }
};

