// src/usecases/report/dateRange.ts
function getDefaultDateRange(startInput, endInput) {
  const now2 = /* @__PURE__ */ new Date();
  let end;
  if (endInput) {
    end = (/* @__PURE__ */ new Date(endInput + "T23:59:59.999Z")).toISOString();
  } else {
    const endDate = new Date(now2);
    endDate.setHours(23, 59, 59, 999);
    end = endDate.toISOString();
  }
  let start;
  if (startInput) {
    start = (/* @__PURE__ */ new Date(startInput + "T00:00:00.000Z")).toISOString();
  } else {
    const startDate = new Date(now2);
    startDate.setFullYear(startDate.getFullYear() - 1);
    startDate.setHours(0, 0, 0, 0);
    start = startDate.toISOString();
  }
  return { start, end };
}

