  const parts2 = [];
  if (criticalCount > 0) parts2.push(`\u{1F534} ${criticalCount} critical`);
  if (warningCount > 0) parts2.push(`\u{1F7E1} ${warningCount} warnings`);
  if (positiveCount > 0) parts2.push(`\u{1F7E2} ${positiveCount} positive`);
  parts2.push(`\u{1F4A1} ${sorted.length - criticalCount - warningCount - positiveCount} info`);
  lines.push(`
${parts2.join("  \u2022  ")}`);
  lines.push(`
\u{1F4A1} **Next actions:**`);
