// src/core/formatters/ProposalFormatter.ts
var ProposalFormatter = class extends BaseFormatter {
  registry;
  constructor() {
    super();
    this.registry = HandleRegistry.getInstance();
  }
  format(data, options) {
    const jsonMode = options?.json === true;
    if (jsonMode) {
      return JSON.stringify(data, null, 2);
    }
    if (Array.isArray(data)) {
      return this.formatList(data);
    }
    const result = data?.searchProposals;
    if (result?.items && Array.isArray(result.items)) {
      return this.formatList(result.items, result.pageInfo);
    }
    return this.formatSingle(data);
  }
  /**
   * Return the user-visible proposal number that matches what the Bookipi
   * web app shows. This is the per-account counter, derived from the
   * auto-generated `title` (format: "Proposal - N").
   *
   * The API also exposes `no`, but that is a GLOBAL cross-tenant counter
   * (e.g. 19073) that nobody else sees. Surfacing it confused users:
   * "the CLI says Proposal-19073 but the web app says Proposal-16."
   *
   * Falls back to the global `no` only if the title was customised and
   * doesn't match the auto-generated pattern — that case is rare, and
   * showing *something* is better than blank.
   */
  getDisplayNumber(proposal) {
    const title = (proposal.title || "").trim();
    const m = title.match(/^Proposal\s*-?\s*(\d+)$/i);
    if (m && m[1]) return m[1];
    return proposal.no?.toString() || "\u2014";
  }
  formatList(proposals, meta3) {
    let output = `# Proposals (${proposals.length} found)
`;
    if (proposals.length === 0) {
      output += "\nNo proposals found.\n";
      return output;
    }
    const headers = ["Handle", "No", "Title", "Customer", "Status", "Total", "Updated"];
    const rows = proposals.map((proposal) => {
      const id = proposal._id || "unknown";
      const handle = this.registry.register("p", id);
      const no = this.getDisplayNumber(proposal);
      const title = proposal.title || "(untitled)";
      const customer = this.getCustomerLabel(proposal);
      const status = this.statusLabel(proposal);
      const total = this.computeTotal(proposal);
      const updated = proposal.updatedAt ? this.formatDate(proposal.updatedAt) : "\u2014";
      return [handle, no, title, customer, status, total, updated];
    });
    output += "\n";
    output += this.createTable(headers, rows, [5]);
    if (meta3) {
      const page = meta3.currentPage ?? 1;
      const pages = meta3.pageCount ?? 1;
      const items = meta3.itemCount ?? proposals.length;
      const perPage = meta3.perPage ?? proposals.length;
      output += `
Page ${page} of ${pages} (${items} total, ${perPage} per page)
`;
    }
    return output;
  }
  formatSingle(proposal) {
    const id = proposal._id || "unknown";
    const handle = this.registry.register("p", id);
    const title = proposal.title || "(untitled proposal)";
    let output = `# Proposal: ${title} [${handle}]
`;
    output += this.section("Details");
    const displayNo = this.getDisplayNumber(proposal);
    if (displayNo !== "\u2014") output += this.listItem("Number", displayNo);
    output += this.listItem("Status", this.statusLabel(proposal));
    output += this.listItem("Total", this.computeTotal(proposal));
    if (proposal.effectiveDate) {
      output += this.listItem("Effective", this.formatDate(proposal.effectiveDate));
    }
    if (proposal.expirationDate) {
      output += this.listItem("Expires", this.formatDate(proposal.expirationDate));
    }
    if (proposal.viewedDate) {
      output += this.listItem("Viewed", this.formatDate(proposal.viewedDate));
    }
    if (proposal.clientSignedDate) {
      output += this.listItem("Signed", this.formatDate(proposal.clientSignedDate));
    }
    if (proposal.updatedAt) {
      output += this.listItem("Last updated", this.formatDate(proposal.updatedAt));
    }
    if (proposal.customerReference || proposal.customer) {
      output += this.section("Customer");
      output += this.listItem("Name", this.getCustomerLabel(proposal));
      const ref = proposal.customerReference;
      if (ref?._id) {
        const customerHandle = this.registry.register("c", ref._id);
        output += this.listItem("Handle", customerHandle);
      }
      if (ref?.email) {
        output += this.listItem("Email", ref.email);
      }
    }
    if (proposal.serviceItems && proposal.serviceItems.length > 0) {
      output += this.section(`Items (${proposal.serviceItems.length})`);
      for (const item of proposal.serviceItems) {
        const name = item.name || "(unnamed)";
        const qty = item.quantity ?? 1;
        const price = this.formatCurrency(item.price);
        const total = this.formatCurrency(item.totalAmount);
        const billing = item.billingType ? ` [${item.billingType}]` : "";
        output += `- ${name} \u2014 ${qty} \xD7 ${price} = ${total}${billing}
`;
      }
    }
    return output;
  }
  getCustomerLabel(proposal) {
    const ref = proposal.customerReference;
    if (ref) {
      if (ref.companyName) return ref.companyName;
      if (ref.individualCompanyName) return ref.individualCompanyName;
      if (ref.email) return ref.email;
    }
    const c = proposal.customer;
    if (c) {
      if (c.companyName) return c.companyName;
      if (c.individualCompanyName) return c.individualCompanyName;
      const fullName = [c.firstName, c.lastName].filter(Boolean).join(" ").trim();
      if (fullName) return fullName;
    }
    return "\u2014";
  }
  statusLabel(proposal) {
    if (proposal.isDraft) return "draft";
    return proposal.status || "\u2014";
  }
  computeTotal(proposal) {
    const items = proposal.serviceItems ?? [];
    if (items.length === 0) return "\u2014";
    const total = items.reduce(
      (sum, item) => sum + (typeof item.totalAmount === "number" ? item.totalAmount : 0),
      0
    );
    if (total <= 0) return "\u2014";
    return this.formatCurrency(total);
  }
};

