// src/usecases/deal/advanceDealStage.ts
var STAGE_ORDER2 = {
  leads: 0,
  qualified: 1,
  meeting: 2,
  proposal: 3,
  contract: 4,
  closed_win: 5,
  closed_lose: 6
};
var TERMINAL_STAGES = /* @__PURE__ */ new Set(["closed_win", "closed_lose"]);
async function advanceDealStage(dealId, target) {
  if (!dealId) {
    return { advanced: false, reason: "no-deal-id" };
  }
  const deal = await getDealById(dealId);
  if (!deal) {
    return { advanced: false, reason: "deal-not-found", dealId };
  }
  const current = deal.status;
  const dealName = deal.name;
  if (!DEAL_STATUSES.includes(current)) {
    return {
      advanced: false,
      reason: "current-key-non-standard",
      from: current,
      to: target,
      dealId,
      ...dealName !== void 0 && { dealName }
    };
  }
  const currentKey = current;
  if (TERMINAL_STAGES.has(currentKey)) {
    return {
      advanced: false,
      reason: "deal-is-terminal",
      from: currentKey,
      to: target,
      dealId,
      ...dealName !== void 0 && { dealName }
    };
  }
  if (STAGE_ORDER2[currentKey] >= STAGE_ORDER2[target]) {
    return {
      advanced: false,
      reason: "already-at-or-past-target",
      from: currentKey,
      to: target,
      dealId,
      ...dealName !== void 0 && { dealName }
    };
  }
  await updateDeal(dealId, { status: target });
  return {
    advanced: true,
    from: currentKey,
    to: target,
    dealId,
    ...dealName !== void 0 && { dealName }
  };
}

