var sendCommand3 = new Command("send").description(
  "Send a proposal by email. Destructive \u2014 the email goes out immediately, so the agent must confirm with the user before running."
).argument("<id>", "Proposal ID or handle (@p1)").requiredOption(
  "-r, --recipients <emails>",
  "Comma-separated list of recipient email addresses"
).option("-b, --bcc <emails>", "Comma-separated list of BCC email addresses").option("-s, --subject <text>", "Email subject line").option("-m, --message <text>", "Email message body").option(
  "--advance-deal",
  "After successful send, also bump the linked deal's stage to 'proposal' (only when the deal isn't already at or past it). See common.md \xA7 Deal Stage Auto-Progression."
).option("--json", "Output raw JSON instead of formatted").action(
  withErrors(async (id, opts) => {
    const registry3 = HandleRegistry.getInstance();
    const resolvedId = registry3.resolve(id);
    const recipients = opts.recipients.split(",").map((e) => e.trim()).filter(Boolean);
    if (recipients.length === 0) {
      failWith("At least one recipient email is required", { json: opts?.json });
    }
    const bcc = opts.bcc ? opts.bcc.split(",").map((e) => e.trim()).filter(Boolean) : [];
    const data = await sendProposal({
      id: resolvedId,
      recipients,
      bcc,
      ...opts.subject !== void 0 && { subject: opts.subject },
      ...opts.message !== void 0 && { message: opts.message }
    });
    let advanceNote = null;
    if (opts.advanceDeal) {
      try {
        const proposal = await getProposalById(resolvedId);
        const dealId = proposal?.projectPipelineId ?? null;
        const result2 = await advanceDealStage(dealId, "proposal");
        if (result2.advanced) {
          registry3.register("d", result2.dealId);
          advanceNote = `Deal '${result2.dealName ?? "unnamed"}' moved: ${result2.from} \u2192 ${result2.to}.`;
        } else {
          switch (result2.reason) {
            case "no-deal-id":
              advanceNote = "No linked deal \u2014 skipped stage update.";
              break;
            case "deal-not-found":
              advanceNote = "Linked deal not found \u2014 skipped.";
              break;
            case "already-at-or-past-target":
              advanceNote = `Deal already at '${result2.from}' (>= proposal) \u2014 no change needed.`;
              break;
            case "deal-is-terminal":
              advanceNote = `Deal is terminal ('${result2.from}') \u2014 leaving alone. Re-opening the deal would need to be explicit.`;
              break;
            case "current-key-non-standard":
              advanceNote = `Deal at custom stage '${result2.from}' \u2014 leaving alone. Move it manually if needed.`;
              break;
          }
        }
      } catch (e) {
        advanceNote = `(Stage update failed: ${e.message}. The proposal was still sent successfully.)`;
      }
    }
    if (opts.json) {
      console.log(JSON.stringify(data, null, 2));
      if (advanceNote) console.log(JSON.stringify({ advanceDeal: advanceNote }, null, 2));
      return;
    }
    const result = data?.proposalsSend;
    const handle = registry3.getHandle(resolvedId) || id;
    console.log(`\u2705 **Proposal Sent**
`);
    console.log(`Proposal ${handle} sent to:`);
    recipients.forEach((email3) => console.log(`  - ${email3}`));
    if (bcc.length > 0) {
      console.log(`
BCC:`);
      bcc.forEach((email3) => console.log(`  - ${email3}`));
    }
    if (opts.subject) console.log(`
Subject: ${opts.subject}`);
    if (result?.message) {
      console.log(`
Server: ${result.message} (status ${result.statusCode ?? "?"})`);
    }
    if (advanceNote) {
      console.log(`
\u{1F4CD} ${advanceNote}`);
    }
    const who = recipients[0] ?? "the customer";
    console.log(
      `
\u{1F4A1} When ${who} accepts, you can either:
   \u2022 Invoice direct:    \`bookipi invoice create-from-proposal ${handle}\`
   \u2022 Or sign-then-bill: \`bookipi contract create-from-proposal ${handle}\` (then \`contract send\`)`
    );
  })
);

