// src/core/auth/signitToken.ts
var REFRESH_LEEWAY_MS2 = 6e4;
var hosted2 = new CallerCache({
  expiresAt: (t) => t.expiryMs - REFRESH_LEEWAY_MS2
});
async function ensureSignitToken() {
  if (currentRequestAuth()) return (await hosted2.get(mintSignitToken)).token;
  const cached2 = getSignitTokenCached();
  if (cached2.token && cached2.expiry && !isExpired2(cached2.expiry)) {
    return cached2.token;
  }
  const fresh = await mintSignitToken();
  saveSignitToken(fresh.token, fresh.expiryMs);
  return fresh.token;
}
async function mintSignitToken() {
  const userToken = getToken();
  if (!userToken) throw new Error("Not logged in");
  const companyId = getDefaultCompany();
  if (!companyId) {
    throw new Error(
      "No default company set \u2014 run 'bookipi whoami' or 'bookipi login' first."
    );
  }
  const data = await graphqlRequest({
    url: config.BOOKIPI_URL,
    query: `query GenerateCustomerSessionKey {
      generateCustomerSessionKey {
        token
        expiry
      }
    }`,
    headers: {
      Authorization: `Bearer ${userToken}`,
      "x-company-id": companyId
    }
  });
  const token = data?.generateCustomerSessionKey?.token;
  const rawExpiry = data?.generateCustomerSessionKey?.expiry;
  if (typeof token !== "string" || !token) {
    throw new Error(
      "Failed to obtain signit token from generateCustomerSessionKey"
    );
  }
  const expiryMs = normaliseExpiry(rawExpiry);
  if (expiryMs == null) {
    throw new Error(
      `generateCustomerSessionKey returned an unrecognised expiry (${typeof rawExpiry}: ${String(rawExpiry)})`
    );
  }
  return { token, expiryMs };
}
function isExpired2(expiryMs) {
  return expiryMs - Date.now() < REFRESH_LEEWAY_MS2;
}
function normaliseExpiry(value) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value > 1e12 ? value : value * 1e3;
  }
  if (typeof value === "string" && value) {
    const parsed = Date.parse(value);
    if (!Number.isNaN(parsed)) return parsed;
    const asNumber = Number(value);
    if (Number.isFinite(asNumber)) {
      return asNumber > 1e12 ? asNumber : asNumber * 1e3;
    }
  }
  return null;
}

// src/core/api/signitClient.ts
async function signitRequest({
  query,
  variables
}) {
  const token = await ensureSignitToken();
  return graphqlRequest({
    url: `${config.SIGNIT_URL}/gql`,
    query,
    variables,
    headers: {
      "x-token": token
    }
  });
}

