// src/core/formatters/ContractFormatter.ts
var ContractFormatter = class extends BaseFormatter {
  registry;
  constructor() {
    super();
    this.registry = HandleRegistry.getInstance();
  }
  format(data, options) {
    const jsonMode = options?.json === true;
    if (jsonMode) {
      return JSON.stringify(data, null, 2);
    }
    if (Array.isArray(data)) {
      return this.formatList(data);
    }
    const result = data?.customerSearchDocumentsSession;
    if (result?.items && Array.isArray(result.items)) {
      return this.formatList(result.items, result.pageInfo, result.count);
    }
    return this.formatSingle(data);
  }
  formatList(contracts, meta3, count) {
    let output = `# Contracts (${contracts.length} found)
`;
    if (contracts.length === 0) {
      output += "\nNo contracts found.\n";
      return output;
    }
    const headers = [
      "Handle",
      "Title",
      "Status",
      "Recipients",
      "Sent",
      "Updated"
    ];
    const rows = contracts.map((contract) => {
      const id = contract._id || "unknown";
      const handle = this.registry.register("k", id);
      const title = contract.title || "(untitled)";
      const status = contract.status || "\u2014";
      const recipients = this.summariseRecipients(contract.recipients);
      const sent = contract.sentDate ? this.formatDate(contract.sentDate) : "\u2014";
      const updated = contract.updatedAt ? this.formatDate(contract.updatedAt) : "\u2014";
      return [handle, title, status, recipients, sent, updated];
    });
    output += "\n";
    output += this.createTable(headers, rows);
    if (meta3) {
      const page = meta3.currentPage ?? 1;
      const pages = meta3.pageCount ?? 1;
      const items = meta3.itemCount ?? count ?? contracts.length;
      const perPage = meta3.perPage ?? contracts.length;
      output += `
Page ${page} of ${pages} (${items} total, ${perPage} per page)
`;
    }
    return output;
  }
  formatSingle(contract) {
    const id = contract._id || "unknown";
    const handle = this.registry.register("k", id);
    const title = contract.title || "(untitled contract)";
    let output = `# Contract: ${title} [${handle}]
`;
    output += this.section("Details");
    output += this.listItem("Status", contract.status || "\u2014");
    if (contract.category) output += this.listItem("Category", contract.category);
    if (contract.type) output += this.listItem("Type", contract.type);
    if (contract.latestAction) {
      output += this.listItem("Latest action", contract.latestAction);
    }
    if (contract.userAction?.action) {
      const userPart = contract.userAction.name ? `${contract.userAction.action} (${contract.userAction.name})` : contract.userAction.action;
      output += this.listItem("Your action", userPart);
    }
    if (contract.allowedActions && contract.allowedActions.length > 0) {
      output += this.listItem("Allowed actions", contract.allowedActions.join(", "));
    }
    if (contract.sentDate) {
      output += this.listItem("Sent", this.formatDate(contract.sentDate));
    }
    if (contract.createdAt) {
      output += this.listItem("Created", this.formatDate(contract.createdAt));
    }
    if (contract.updatedAt) {
      output += this.listItem("Updated", this.formatDate(contract.updatedAt));
    }
    if (contract.recipients && contract.recipients.length > 0) {
      output += this.section(`Recipients (${contract.recipients.length})`);
      for (const r of contract.recipients) {
        const name = r.fullName || r.email || "(unnamed)";
        const role = r.role ? ` [${r.role}]` : "";
        const email3 = r.email && r.fullName ? ` \u2014 ${r.email}` : "";
        output += `- ${name}${role}${email3}
`;
      }
    }
    if (contract.originalFileUrl || contract.signedFile || contract.latestSignedDocumentUrl) {
      output += this.section("Files");
      if (contract.originalFileUrl) {
        output += this.listItem("Original", contract.originalFileUrl);
      }
      if (contract.signedFile) {
        output += this.listItem("Signed", contract.signedFile);
      }
      if (contract.latestSignedDocumentUrl) {
        output += this.listItem("Latest signed", contract.latestSignedDocumentUrl);
      }
    }
    return output;
  }
  summariseRecipients(recipients) {
    if (!recipients || recipients.length === 0) return "\u2014";
    if (recipients.length === 1) {
      const r = recipients[0];
      return r.fullName || r.email || "(unnamed)";
    }
    const first = recipients[0];
    const firstLabel = first.fullName || first.email || "?";
    return `${firstLabel} +${recipients.length - 1}`;
  }
};

