// src/usecases/contract/uploadContractDocument.ts
import fs7 from "node:fs";
import path8 from "node:path";

// src/usecases/contract/uploadDocumentPDF.ts
var GET_UPLOAD_URL_QUERY = `
  query GetDocumentUploadUrl($documentId: MongoID!, $contentType: EnumDocumentFileContentType!) {
    getDocumentUploadUrl(documentId: $documentId, contentType: $contentType) {
      url
      fields
    }
  }
`;
var MIME = {
  pdf: "application/pdf",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  doc: "application/msword"
};
async function uploadDocumentFile(opts) {
  const mime = MIME[opts.contentType] || "application/octet-stream";
  const data = await signitRequest({
    query: GET_UPLOAD_URL_QUERY,
    variables: { documentId: opts.documentId, contentType: opts.contentType }
  });
  const upload = data?.getDocumentUploadUrl;
  if (!upload?.url) {
    throw new Error("getDocumentUploadUrl returned no URL");
  }
  const url2 = upload.url;
  let fields = {};
  if (typeof upload.fields === "string") {
    try {
      fields = JSON.parse(upload.fields);
    } catch (e) {
      throw new Error(
        `getDocumentUploadUrl returned non-JSON fields: ${e.message}`
      );
    }
  } else if (upload.fields && typeof upload.fields === "object") {
    fields = upload.fields;
  }
  const form = new FormData();
  for (const [k, v] of Object.entries(fields)) {
    form.append(k, v);
  }
  if (!("Content-Type" in fields)) {
    form.append("Content-Type", mime);
  }
  const buffer = Buffer.from(opts.base64, "base64");
  const blob = new Blob([new Uint8Array(buffer)], { type: mime });
  form.append("file", blob, opts.fileName || `document.${opts.contentType}`);
  let res;
  try {
    res = await fetch(url2, { method: "POST", body: form });
  } catch (err2) {
    const cause = err2?.cause?.message || err2?.cause?.code || err2?.message || "unknown";
    throw new Error(
      `S3 upload request failed before response: ${cause} (target: ${url2})`
    );
  }
  if (res.status < 200 || res.status >= 300) {
    const body = await res.text().catch(() => "");
    throw new Error(`S3 upload failed: ${res.status} ${body.slice(0, 500)}`);
  }
  return { uploaded: true, url: url2, statusCode: res.status };
}
async function uploadDocumentPDF(opts) {
  return uploadDocumentFile({
    documentId: opts.documentId,
    base64: opts.pdfBase64,
    contentType: "pdf"
  });
}

// src/usecases/contract/uploadContractDocument.ts
var CREATE_DOC = `
  mutation documentsCreateOne($record: createDocumentRecordITCWrapped!) {
    documentsCreateOne(record: $record) {
      recordId
      record { _id title status }
    }
  }
`;
var UPDATE_DOC = `
  mutation documentsUpdateOne($record: UpdateOnedocumentsInputWrapped!, $filter: updateDocumentFilterITC) {
    documentsUpdateOne(record: $record, filter: $filter) {
      recordId
      record { _id title status }
    }
  }
`;
function contentTypeFor(filePath) {
  const ext = path8.extname(filePath).replace(/^\./, "").toLowerCase();
  if (!ext) {
    throw new Error(`Can't determine file type from "${filePath}" \u2014 add an extension (e.g. .pdf)`);
  }
  return ext === "jpeg" ? "jpg" : ext;
}
async function uploadContractDocument(opts) {
  const { filePath } = opts;
  if (!fs7.existsSync(filePath)) throw new Error(`File not found: ${filePath}`);
  const bytes = fs7.readFileSync(filePath);
  if (!bytes.length) throw new Error(`File is empty: ${filePath}`);
  const contentType3 = contentTypeFor(filePath);
  const fileName = path8.basename(filePath);
  const nameNoExt = fileName.replace(/\.[^.]+$/, "");
  const title = opts.title?.trim() || nameNoExt;
  const documentId = await generateDocumentId();
  await signitRequest({
    query: CREATE_DOC,
    variables: { record: { _id: documentId, title: "New Document" } }
  });
  await uploadDocumentFile({
    documentId,
    base64: bytes.toString("base64"),
    contentType: contentType3,
    fileName
  });
  await signitRequest({
    query: UPDATE_DOC,
    variables: {
      filter: { _id: documentId },
      record: { title, meta: { originalFileName: nameNoExt } }
    }
  });
  return { documentId, title, contentType: contentType3 };
}

