// src/commands/contract/send.ts
var sendCommand4 = new Command("send").description(
  "Send a contract for signature. Flips status to `pending_signature`, which triggers email delivery to all recipients. **Destructive \u2014 confirm with the user before invoking.**"
).argument("<id>", "Contract ID or handle (@k1)").option(
  "--advance-deal",
  "After successful send, also bump the linked deal's stage to 'contract' (only when the deal isn't already at or past it). Optional \u2014 only applies when the contract is somehow linked to a deal externally (e.g. via the proposal it was created from)."
).option(
  "--deal <value>",
  "Deal handle (@d1) or ID to advance after send. Required if you want to use --advance-deal \u2014 the contract record itself doesn't store the deal link."
).option("--json", "Output raw JSON instead of formatted").action(
  withErrors(async (id, opts) => {
    const registry3 = HandleRegistry.getInstance();
    const contractId = registry3.resolve(id);
    const contract = await getDocument(contractId);
    if (contract.status === "pending_signature") {
      console.log(
        `Contract is already at \`pending_signature\` \u2014 already sent. No action taken.`
      );
      if (opts.json) {
        console.log(JSON.stringify({ alreadySent: true, contract }, null, 2));
      }
      return;
    }
    if (!Array.isArray(contract.recipients) || contract.recipients.length === 0) {
      throw new Error(
        "Contract has no recipients \u2014 add at least one signer before sending. Use the editor link from `contract create-from-proposal` output."
      );
    }
    if (!Array.isArray(contract.tags) || contract.tags.length === 0) {
      throw new Error(
        "Contract has no signature tags \u2014 drop at least one in the editor before sending."
      );
    }
    const sendRes = await updateDocument({
      documentId: contractId,
      record: {
        title: contract.title ?? "Untitled Contract",
        category: contract.category ?? "Finance",
        recipients: contract.recipients.map((r) => ({
          _id: r._id,
          role: r.role ?? "signer",
          mySelf: r.mySelf ?? false
        })),
        status: "pending_signature"
      }
    });
    const updated = sendRes?.documentsUpdateOne?.record;
    let advanceNote = null;
    if (opts.advanceDeal) {
      if (!opts.deal) {
        advanceNote = "(Skipped --advance-deal: --deal <handle|id> is required because contracts don't store the deal link directly.)";
      } else {
        try {
          const dealId = registry3.resolve(opts.deal);
          const result = await advanceDealStage(dealId, "contract");
          if (result.advanced) {
            advanceNote = `Deal '${result.dealName ?? "unnamed"}' moved: ${result.from} \u2192 ${result.to}.`;
          } else {
            switch (result.reason) {
              case "no-deal-id":
                advanceNote = "No linked deal \u2014 skipped stage update.";
                break;
              case "deal-not-found":
                advanceNote = "Linked deal not found \u2014 skipped.";
                break;
              case "already-at-or-past-target":
                advanceNote = `Deal already at '${result.from}' (>= contract) \u2014 no change needed.`;
                break;
              case "deal-is-terminal":
                advanceNote = `Deal is terminal ('${result.from}') \u2014 leaving alone.`;
                break;
              case "current-key-non-standard":
                advanceNote = `Deal at custom stage '${result.from}' \u2014 leaving alone.`;
                break;
            }
          }
        } catch (e) {
          advanceNote = `(Stage update failed: ${e.message}. The contract was still sent successfully.)`;
        }
      }
    }
    const handle = registry3.getHandle(contractId) || id;
    if (opts.json) {
      console.log(JSON.stringify({ sent: true, contract: updated, advanceNote }, null, 2));
      return;
    }
    const recipients = updated?.recipients ?? contract.recipients;
    console.log(`\u2705 **Contract Sent for Signature**
`);
    console.log(`Contract ${handle} (${contract.title}) sent to:`);
    for (const r of recipients) {
      console.log(`  - ${r.fullName || "(unnamed)"} <${r.email}>`);
    }
    console.log(`
Status: ${updated?.status ?? "?"}`);
    if (advanceNote) {
      console.log(`
\u{1F4CD} ${advanceNote}`);
    }
  })
);

