// src/mcp/result.ts
function ok(data) {
  const text = typeof data === "string" ? data : JSON.stringify(data);
  return { content: [{ type: "text", text }] };
}
function responseBytes(result) {
  const content = result?.content;
  if (!Array.isArray(content)) return 0;
  return content.reduce((total, part) => total + (part?.text?.length ?? 0), 0);
}
function estTokens(bytes) {
  return Math.round(bytes / 4);
}
function fail(err2) {
  const message = err2 instanceof Error ? err2.message : String(err2);
  return {
    isError: true,
    content: [{ type: "text", text: `Error: ${message}` }]
  };
}

// src/mcp/readTools.ts
function registerReadTools(server) {
  for (const entry of registry2) {
    if (!entry.readOnly) continue;
    server.registerTool(
      entry.name,
      {
        title: entry.title,
        description: entry.description,
        // `.strict()` and a ZodObject, not `.shape` — see the note above.
        inputSchema: entry.inputSchema.strict(),
        annotations: {
          readOnlyHint: true,
          // readOnlyHint:true implies this, but the ChatGPT submission portal
          // checks each hint explicitly and blocks the rescan on its absence.
          destructiveHint: false,
          idempotentHint: true,
          // False: these read the signed-in user's own Bookipi account. OpenAI
          // reviews openWorldHint as "public internet or open-ended external
          // entities" and says a bounded private account is not open-world
          // just because it is hosted — v1.0.0 was rejected for claiming it.
          openWorldHint: false
        }
      },
      async (args) => {
        try {
          return ok(await entry.run(args));
        } catch (err2) {
          return fail(err2);
        }
      }
    );
  }
}
var READ_TOOL_NAMES = registry2.filter((e) => e.readOnly).map((e) => e.name);

