async function recentDuplicate(companyId, customerId, record2) {
  try {
    const data = await listInvoices({
      customerId,
      companyId,
      perPage: 10,
      sort: "createdAt_desc"
    });
    const rows = data.searchInvoices?.items;
    if (!Array.isArray(rows)) return null;
    const wanted = lineSignature(record2.items);
    const cutoff = Date.now() - DUPLICATE_WINDOW_MS;
    for (const row of rows) {
      const createdAt = Date.parse(String(row["createdAt"] ?? ""));
      if (!Number.isFinite(createdAt) || createdAt < cutoff) continue;
      if (Number(row["total"]) !== Number(record2.total)) continue;
      if (lineSignature(row["items"]) !== wanted) continue;
      return {
        _id: String(row["_id"]),
        no: String(row["no"] ?? "(no number)")
      };
    }
    return null;
  } catch {
    return null;
  }
}
function lineSignature(items) {
  if (!Array.isArray(items)) return "";
  return items.map((i) => {
    const line = i ?? {};
    return [
      String(line["name"] ?? ""),
      Number(line["quantity"] ?? 0),
      Number(line["price"] ?? 0)
    ].join("");
  }).join("");
}

